            llvm::Value* is_min = builder->CreateICmpEQ(l_int,
                llvm::ConstantInt::getSigned(i64_type, INT64_MIN));
            llvm::Value* is_negative_one = builder->CreateICmpEQ(r_int,
                llvm::ConstantInt::getSigned(i64_type, -1));
